param(\n    [Parameter(Mandatory=$true)][string]$Eboot,\n    [string]$Ps3Recomp = "local/ps3recomp",\n    [string]$AnalysisDir = "analysis/generated/loader",\n    [string]$RecompDir = "port/recompiled",\n    [string]$BuildDir = "build",\n    [string]$VfsRoot = "",\n    [switch]$Run\n)\n\n$ErrorActionPreference = "Stop"\n$Pin = "e2815326c58d3530936166982672cb09acdef4f9"\n\nforeach ($cmd in @("python","cmake","ninja","clang-cl","git")) {\n    if (-not (Get-Command $cmd -ErrorAction SilentlyContinue)) { throw "$cmd is required and was not found in PATH" }\n}\n\n$Observed = (git -C $Ps3Recomp rev-parse HEAD).Trim()\nif ($Observed -ne $Pin) { throw "ps3recomp revision mismatch: expected $Pin, got $Observed" }\nif (-not (Test-Path $Eboot)) { throw "EBOOT ELF not found: $Eboot" }\n\n$Functions = Get-ChildItem $AnalysisDir -Filter "*.functions.json" | Select-Object -First 1\n$Imports = Get-ChildItem $AnalysisDir -Filter "*.imports.json" | Select-Object -First 1\nif (-not $Functions -or -not $Imports) { throw "M1 loader metadata missing. Run tools/m1_analyze.py first." }\n\nNew-Item -ItemType Directory -Force -Path $RecompDir | Out-Null\n$ResolvedSdk = (Resolve-Path $Ps3Recomp).Path\n$ResolvedRecomp = (Resolve-Path $RecompDir).Path\n$ResolvedEboot = (Resolve-Path $Eboot).Path\n\n$LifterArgs = @(\n    "$ResolvedSdk/tools/ppu_lifter.py", $ResolvedEboot,\n    "--functions", $Functions.FullName,\n    "--hle-stubs", $Imports.FullName,\n    "--output", $ResolvedRecomp\n)\npython @LifterArgs\n\n$NidArgs = @("$ResolvedSdk/tools/gen_hle_nids.py", "--all", "--out", "$ResolvedRecomp/ppu_hle_nids.cpp")\npython @NidArgs\n\n$CmakeArgs = @(\n    "-S", "port", "-B", $BuildDir, "-G", "Ninja",\n    "-DPS3RECOMP_DIR=$ResolvedSdk",\n    "-DRECOMP_DIR=$ResolvedRecomp",\n    "-DCMAKE_C_COMPILER=clang-cl",\n    "-DCMAKE_CXX_COMPILER=clang-cl"\n)\ncmake @CmakeArgs\ncmake --build $BuildDir --parallel\n\nif ($Run) {\n    $Exe = Join-Path $BuildDir "CometCrashRecomp.exe"\n    if (-not (Test-Path $Exe)) { throw "Built executable not found: $Exe" }\n    New-Item -ItemType Directory -Force -Path "local/logs" | Out-Null\n    $Stamp = Get-Date -Format "yyyyMMdd-HHmmss"\n    if ($VfsRoot) { $env:PS3_VFS_ROOT = (Resolve-Path $VfsRoot).Path }\n    $env:PS3_TITLE = "Comet Crash"\n    & $Exe $ResolvedEboot 2>&1 | Tee-Object -FilePath "local/logs/boot-$Stamp.log"\n}\n